INSERT INTO exercises (id, name, category, equipment, target, muscle_group, secondary_muscles, instructions_es, image_url, gif_url) VALUES
('0358', 'dumbbell one arm reverse wrist curl', 'lower arms', 'dumbbell', 'forearms', 'wrist extensors', '{"wrist extensors"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo. Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde. Baja lentamente la mancuerna hacia el suelo flexionando la muñeca. Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0358-BwSNDGt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0358-BwSNDGt.gif'),
('0359', 'dumbbell one arm reverse fly (with support)', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro. Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte. Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0359-e25F58f.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0359-e25F58f.gif'),
('1622', 'dumbbell one arm reverse grip press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo. Coloca los pies planos sobre el suelo y mantén la espalda recta. Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1622-Ze7MoIb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1622-Ze7MoIb.gif'),
('1414', 'dumbbell one arm reverse preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino. Baja lentamente la mancuerna hasta que el brazo quede completamente extendido. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1414-bWxq4op.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1414-bWxq4op.gif'),
('1667', 'dumbbell one arm reverse spider curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1667-VdLZ3nB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1667-VdLZ3nB.gif'),
('1668', 'dumbbell one arm seated bicep curl on exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1668-s999Hdo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1668-s999Hdo.gif'),
('1669', 'dumbbell one arm seated hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí). Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1669-jK2hZ6n.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1669-jK2hZ6n.gif'),
('1415', 'dumbbell one arm seated neutral wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde. Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra mano.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1415-YtaCTYl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1415-YtaCTYl.gif'),
('0361', 'dumbbell one arm shoulder press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0361-84RyJf8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0361-84RyJf8.gif'),
('0360', 'dumbbell one arm shoulder press v. 2', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0360-1TkiAFK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0360-1TkiAFK.gif'),
('3888', 'dumbbell one arm snatch', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo. Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta. Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo. Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3888-6pTkI99.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3888-6pTkI99.gif'),
('1670', 'dumbbell one arm standing curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1670-ffQsyBj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1670-ffQsyBj.gif'),
('1671', 'dumbbell one arm standing hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1671-2sQGZ5b.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1671-2sQGZ5b.gif'),
('0362', 'dumbbell one arm triceps extension (on bench)', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0362-nAuHPcD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0362-nAuHPcD.gif'),
('0363', 'dumbbell one arm upright row', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0363-6cKQC5E.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0363-6cKQC5E.gif'),
('0364', 'dumbbell one arm wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo. Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Repite el número de repeticiones deseado, luego cambia a la otra mano.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0364-q8aHNoF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0364-q8aHNoF.gif'),
('1672', 'dumbbell one arm zottman preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino. Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba. Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1672-sxY5Biu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1672-sxY5Biu.gif'),
('1292', 'dumbbell one leg fly on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante. Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho. Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1292-pH2x2jj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1292-pH2x2jj.gif'),
('0365', 'dumbbell over bench neutral wrist curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0365-BKa8dmT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0365-BKa8dmT.gif'),
('0366', 'dumbbell over bench one arm neutral wrist curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0366-IvV6C9M.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0366-IvV6C9M.gif'),
('1441', 'dumbbell over bench one arm reverse wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1441-4Jc36XM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1441-4Jc36XM.gif'),
('0367', 'dumbbell over bench one arm wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0367-KI1DjNN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0367-KI1DjNN.gif'),
('0368', 'dumbbell over bench revers wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0368-3tAXPQ6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0368-3tAXPQ6.gif'),
('0369', 'dumbbell over bench wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano. Deja que tus muñecas cuelguen del borde del banco. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0369-D1xYJAU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0369-D1xYJAU.gif'),
('1329', 'dumbbell palm rotational bent over row', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo. Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo. Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1329-wt6rwjk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1329-wt6rwjk.gif'),
('1623', 'dumbbell palms in incline bench press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro. Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos. Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1623-8eqjhOl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1623-8eqjhOl.gif'),
('0370', 'dumbbell peacher hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0370-F1KxjBa.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0370-F1KxjBa.gif'),
('0371', 'dumbbell plyo squat', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo. Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante. Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies. Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0371-S4pwGlc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0371-S4pwGlc.gif'),
('0372', 'dumbbell preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0372-jivWf8n.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0372-jivWf8n.gif'),
('1673', 'dumbbell preacher curl over exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1673-hwygydB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1673-hwygydB.gif'),
('1293', 'dumbbell press on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1293-O8o7q4d.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1293-O8o7q4d.gif'),
('0373', 'dumbbell pronate-grip triceps extension', 'upper arms', 'dumbbell', 'triceps', 'forearms', '{"forearms"}', 'Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza. Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0373-bpJL2Qs.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0373-bpJL2Qs.gif'),
('0374', 'dumbbell prone incline curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0374-mwpPcr1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0374-mwpPcr1.gif'),
('1674', 'dumbbell prone incline hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí. Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1674-cWemPG8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1674-cWemPG8.gif'),
('0375', 'dumbbell pullover', 'chest', 'dumbbell', 'pectorals', 'latissimus dorsi', '{"latissimus dorsi","triceps"}', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0375-9XjtHvS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0375-9XjtHvS.gif'),
('1294', 'dumbbell pullover hip extension on exercise ball', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core. Baja las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1294-lI7easp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1294-lI7easp.gif'),
('1295', 'dumbbell pullover on exercise ball', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","latissimus dorsi"}', 'Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1295-FSD6PGL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1295-FSD6PGL.gif'),
('1700', 'dumbbell push press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza. Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1700-FS63wTN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1700-FS63wTN.gif'),
('0376', 'dumbbell raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0376-c9MnDRp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0376-c9MnDRp.gif'),
('2292', 'dumbbell rear delt raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2292-mu5Guxt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2292-mu5Guxt.gif'),
('0377', 'dumbbell rear delt row_shoulder', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos. Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0377-EKXOMEh.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0377-EKXOMEh.gif'),
('0378', 'dumbbell rear fly', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0378-8DiFDVA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0378-8DiFDVA.gif'),
('0380', 'dumbbell rear lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0380-v1qBec9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0380-v1qBec9.gif'),
('0379', 'dumbbell rear lateral raise (support head)', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0379-UzkLrem.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0379-UzkLrem.gif'),
('0381', 'dumbbell rear lunge', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada. Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial. Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0381-SSsBDwB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0381-SSsBDwB.gif'),
('0382', 'dumbbell revers grip biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0382-e4ojVhP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0382-e4ojVhP.gif'),
('1624', 'dumbbell reverse bench press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies. Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1624-UIbGx6H.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1624-UIbGx6H.gif'),
('0383', 'dumbbell reverse fly', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0383-EAs3xL9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0383-EAs3xL9.gif'),
('1330', 'dumbbell reverse grip incline bench one arm row', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Coloca una mancuerna en el suelo junto al banco. Ponte de pie frente al banco con los pies separados a la altura de los hombros. Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte. Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo). Mantén la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Aprieta los músculos de la espalda en la parte superior del movimiento. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo izquierdo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1330-ZIViNh1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1330-ZIViNh1.gif'),
('1331', 'dumbbell reverse grip incline bench two arm row', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre supino. Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1331-9pQSkH8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1331-9pQSkH8.gif'),
('2327', 'dumbbell reverse grip row (female)', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2327-Nh3mvOO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2327-Nh3mvOO.gif'),
('0384', 'dumbbell reverse preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba. Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps. Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0384-O8Aq69u.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0384-O8Aq69u.gif'),
('1675', 'dumbbell reverse spider curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1675-6sMAmNv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1675-6sMAmNv.gif'),
('0385', 'dumbbell reverse wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0385-BLCvwr2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0385-BLCvwr2.gif'),
('1459', 'dumbbell romanian deadlift', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1459-rR0LJzx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1459-rR0LJzx.gif'),
('0386', 'dumbbell rotation reverse fly', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Gira los brazos de modo que las palmas queden mirando hacia abajo. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0386-prbWx1D.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0386-prbWx1D.gif'),
('2397', 'dumbbell scott press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","chest"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2397-5vfAI0I.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2397-5vfAI0I.gif'),
('0387', 'dumbbell seated alternate front raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","biceps"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados. Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0387-gH5fRsC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0387-gH5fRsC.gif'),
('1676', 'dumbbell seated alternate hammer curl on exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1676-QLRmNeT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1676-QLRmNeT.gif'),
('0388', 'dumbbell seated alternate press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","chest"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0388-QT5Q0nK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0388-QT5Q0nK.gif'),
('3546', 'dumbbell seated alternate shoulder', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros. Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros. Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza. Continúa alternando entre los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3546-q7qkONO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3546-q7qkONO.gif'),
('0389', 'dumbbell seated bench extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0389-JhYSVwT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0389-JhYSVwT.gif'),
('2317', 'dumbbell seated bent arm lateral raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados. Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2317-JzQbv7J.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2317-JzQbv7J.gif'),
('1730', 'dumbbell seated bent over alternate kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","back"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido. Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1730-x0lwvfq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1730-x0lwvfq.gif'),
('1737', 'dumbbell seated bent over triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","back"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y la cabeza erguida. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca de la cabeza. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1737-4ievMJ9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1737-4ievMJ9.gif'),
('1677', 'dumbbell seated bicep curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1677-xiA6lRr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1677-xiA6lRr.gif'),
('0390', 'dumbbell seated biceps curl (on stability ball)', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0390-WgJnBH5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0390-WgJnBH5.gif'),
('3547', 'dumbbell seated biceps curl to shoulder press', 'upper arms', 'dumbbell', 'biceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros. Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante. Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos. Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3547-OeL23VY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3547-OeL23VY.gif'),
('1379', 'dumbbell seated calf raise', 'lower legs', 'dumbbell', 'calves', 'hamstrings', '{"hamstrings"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos. Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde. Sujétate de la mancuerna para mantener la estabilidad. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1379-r29jP7S.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1379-r29jP7S.gif'),
('0391', 'dumbbell seated curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0391-TiaZTxx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0391-TiaZTxx.gif'),
('0392', 'dumbbell seated front raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","biceps"}', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0392-Ys97II0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0392-Ys97II0.gif'),
('1678', 'dumbbell seated hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1678-IGtBdNT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1678-IGtBdNT.gif'),
('0393', 'dumbbell seated inner biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo. Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0393-KXyoEtA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0393-KXyoEtA.gif'),
('0394', 'dumbbell seated kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0394-en550rk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0394-en550rk.gif'),
('0396', 'dumbbell seated lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","upper back"}', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0396-hxyTtWj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0396-hxyTtWj.gif'),
('0395', 'dumbbell seated lateral raise v. 2', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","triceps"}', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0395-hrrS0Ed.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0395-hrrS0Ed.gif'),
('0397', 'dumbbell seated neutral wrist curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí. Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo. Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0397-uJmK7Z1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0397-uJmK7Z1.gif'),
('1679', 'dumbbell seated one arm bicep curl on exercise ball with leg raised', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Coloca la otra mano en la cadera para mantener el equilibrio. Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo. Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1679-84sESNy.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1679-84sESNy.gif'),
('0398', 'dumbbell seated one arm kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano. Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0398-VQ3sNCn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0398-VQ3sNCn.gif'),
('0399', 'dumbbell seated one arm rotate', 'lower arms', 'dumbbell', 'forearms', 'shoulders', '{"shoulders","biceps"}', 'Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo. Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo. Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo. Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0399-7f2jsqP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0399-7f2jsqP.gif'),
('0400', 'dumbbell seated one leg calf raise', 'lower legs', 'dumbbell', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho. Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado. Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso. Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0400-Ia7tumC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0400-Ia7tumC.gif'),
('1380', 'dumbbell seated one leg calf raise - hammer grip', 'lower legs', 'dumbbell', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos. Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde. Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra. Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1380-FxhcxUW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1380-FxhcxUW.gif'),
('1381', 'dumbbell seated one leg calf raise - palm up', 'lower legs', 'dumbbell', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba. Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada. Eleva el talón lo más alto posible empujando con la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1381-VW88JNd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1381-VW88JNd.gif'),
('0401', 'dumbbell seated palms up wrist curl', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0401-2dImyQ8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0401-2dImyQ8.gif'),
('0402', 'dumbbell seated preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con los pies apoyados en el suelo. Sujeta una mancuerna con una mano con agarre supino, apoyando la parte superior del brazo en la almohadilla del banco scott. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0402-7D5bgLT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0402-7D5bgLT.gif'),
('0403', 'dumbbell seated revers grip concentration curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0403-lyKCLmK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0403-lyKCLmK.gif'),
('1738', 'dumbbell seated reverse grip one arm overhead tricep extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1738-5fKX7wi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1738-5fKX7wi.gif'),
('0405', 'dumbbell seated shoulder press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0405-znQUdHY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0405-znQUdHY.gif'),
('0404', 'dumbbell seated shoulder press (parallel grip)', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0404-f1jf47L.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0404-f1jf47L.gif'),
('2188', 'dumbbell seated triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2188-kont8Ut.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2188-kont8Ut.gif'),
('0406', 'dumbbell shrug', 'back', 'dumbbell', 'traps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados. Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos. Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0406-NJzBsGJ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0406-NJzBsGJ.gif'),
('0407', 'dumbbell side bend', 'waist', 'dumbbell', 'abs', 'obliques', '{"obliques"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado. Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0407-IpONWYv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0407-IpONWYv.gif'),
('0408', 'dumbbell side lying one hand raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo. Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo. Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0408-fTlkJop.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0408-fTlkJop.gif'),
('3664', 'dumbbell side plank with rear fly', 'back', 'dumbbell', 'upper back', 'shoulders', '{"shoulders","core"}', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados. Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones. Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3664-X6ytgYZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3664-X6ytgYZ.gif'),
('3548', 'dumbbell single arm overhead carry', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza. Continúa caminando durante la distancia o el tiempo deseado. Cambia de mano y repite el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3548-mWBtgmb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3548-mWBtgmb.gif'),
('0409', 'dumbbell single leg calf raise', 'lower legs', 'dumbbell', 'calves', 'ankles', '{"ankles"}', 'Ponte de pie en el borde de un escalón o plataforma, con los talones colgando y la punta de los pies sobre el escalón. Sujeta una mancuerna con una mano y coloca la otra mano sobre una pared o barandilla para apoyarte. Eleva el talón lo más alto posible, levantando el cuerpo sobre la punta de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón por debajo del nivel del escalón. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0409-1kB3Wmk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0409-1kB3Wmk.gif'),
('1757', 'dumbbell single leg deadlift', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha. Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo. Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo. Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda. Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo. Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1757-gKozT8X.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1757-gKozT8X.gif'),
('2805', 'dumbbell single leg deadlift with stepbox support', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha. Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti. Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo. Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón. Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2805-daBmy1Y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2805-daBmy1Y.gif'),
('0410', 'dumbbell single leg split squat', 'upper legs', 'dumbbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón. Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo. Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0410-qx4fgX7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0410-qx4fgX7.gif'),
('0411', 'dumbbell single leg squat', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0411-H6ybluc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0411-H6ybluc.gif'),
('0413', 'dumbbell squat', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0413-HsvHqgf.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0413-HsvHqgf.gif'),
('3560', 'dumbbell standing alternate hammer curl and press', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y la espalda recta. Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el curl con la mano izquierda. Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza. Extiende completamente el brazo y mantén la posición por un momento en la parte superior. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el press con la mano izquierda. Continúa alternando entre curls y press durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3560-LeaZOIz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3560-LeaZOIz.gif'),
('0414', 'dumbbell standing alternate overhead press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante. Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0414-bBi35y3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0414-bBi35y3.gif'),
('0415', 'dumbbell standing alternate raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y el core activado. Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0415-SxHteRW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0415-SxHteRW.gif'),
('1739', 'dumbbell standing alternating tricep kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite con el otro brazo, alternando lados en cada repetición.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1739-Gi2BXfK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1739-Gi2BXfK.gif'),
('2143', 'dumbbell standing around world', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo. Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza. Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2143-RSOsp5d.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2143-RSOsp5d.gif'),
('1740', 'dumbbell standing bent over one arm triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1740-CJwa0vD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1740-CJwa0vD.gif'),
('1741', 'dumbbell standing bent over two arm triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo. Baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1741-3T12T87.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1741-3T12T87.gif'),
('0416', 'dumbbell standing biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0416-3s4NnTh.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0416-3s4NnTh.gif'),
('0417', 'dumbbell standing calf raise', 'lower legs', 'dumbbell', 'calves', 'ankles', '{"ankles"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0417-dPmaUaU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0417-dPmaUaU.gif'),
('0418', 'dumbbell standing concentration curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0418-7inpWch.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0418-7inpWch.gif'),
('0419', 'dumbbell standing front raise above head', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0419-laVRfDf.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0419-laVRfDf.gif'),
('2321', 'dumbbell standing inner biceps curl v. 2', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones recomendado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2321-vKilzz3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2321-vKilzz3.gif'),
('0420', 'dumbbell standing kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0420-UmpPAAe.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0420-UmpPAAe.gif'),
('0421', 'dumbbell standing one arm concentration curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba. Coloca la mano libre sobre el muslo para apoyarte. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0421-8fgqP5a.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0421-8fgqP5a.gif'),
('0422', 'dumbbell standing one arm curl (over incline bench)', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0422-BIb1tGo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0422-BIb1tGo.gif'),
('1680', 'dumbbell standing one arm curl over incline bench', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1680-EmlJR2y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1680-EmlJR2y.gif'),
('0423', 'dumbbell standing one arm extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo. Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0423-BCUR88E.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0423-BCUR88E.gif'),
('0424', 'dumbbell standing one arm palm in press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro. Activa el core y mantén la espalda recta. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0424-ocYc6Db.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0424-ocYc6Db.gif'),
('0425', 'dumbbell standing one arm reverse curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono. Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo. Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0425-DU5Kkj2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0425-DU5Kkj2.gif'),
('0426', 'dumbbell standing overhead press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0426-A6wtbuL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0426-A6wtbuL.gif'),
('0427', 'dumbbell standing palms in press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","chest"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro. Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0427-UilDHSs.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0427-UilDHSs.gif'),
('0428', 'dumbbell standing preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0428-hq2hyDH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0428-hq2hyDH.gif'),
('0429', 'dumbbell standing reverse curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo. Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0429-0IgNjSM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0429-0IgNjSM.gif'),
('0430', 'dumbbell standing triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto. Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo. Extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0430-PdmaD0N.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0430-PdmaD0N.gif'),
('2293', 'dumbbell standing zottman preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados. Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos. En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2293-P2nRiUa.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2293-P2nRiUa.gif'),
('1684', 'dumbbell step up single leg balance with bicep curl', 'upper arms', 'dumbbell', 'biceps', 'quadriceps', '{"quadriceps","glutes","hamstrings"}', 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie. Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho. En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros. Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo. Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1684-76vfTdU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1684-76vfTdU.gif'),
('0431', 'dumbbell step-up', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón derecho y sube el cuerpo sobre el banco o escalón, enderezando la pierna derecha. Sube el pie izquierdo hasta el banco o escalón, quedando completamente erguido. Baja con el pie izquierdo, seguido del pie derecho, volviendo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0431-aXtJhlg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0431-aXtJhlg.gif'),
('2796', 'dumbbell step-up lunge', 'upper legs', 'dumbbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie. Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba. Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón. Repite el movimiento, alternando el pie con el que subes cada vez. Continúa durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2796-gFyFj9z.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2796-gFyFj9z.gif'),
('2812', 'dumbbell step-up split squat', 'upper legs', 'dumbbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo. Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho. Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón. Repite el movimiento con el pie izquierdo sobre el banco o escalón. Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2812-QjE2DcA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2812-QjE2DcA.gif'),
('0432', 'dumbbell stiff leg deadlift', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0432-5eLRITT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0432-5eLRITT.gif'),
('0433', 'dumbbell straight arm pullover', 'chest', 'dumbbell', 'pectorals', 'latissimus dorsi', '{"latissimus dorsi","triceps"}', 'Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0433-i8BdLTK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0433-i8BdLTK.gif'),
('0434', 'dumbbell straight leg deadlift', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante. Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0434-oom75KC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0434-oom75KC.gif'),
('2808', 'dumbbell sumo pull through', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","core"}', 'Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera. Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos. Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta. Baja la mancuerna entre las piernas, manteniendo los brazos rectos. Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo. Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2808-BmrwWzo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2808-BmrwWzo.gif'),
('2803', 'dumbbell supported squat', 'upper legs', 'dumbbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2803-r5DgrW9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2803-r5DgrW9.gif'),
('0436', 'dumbbell tate press', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí. Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros. Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0436-s5PdDyY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0436-s5PdDyY.gif'),
('1742', 'dumbbell tricep kickback with stork stance', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, apretando el tríceps. Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1742-wOLmCXc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1742-wOLmCXc.gif'),
('1743', 'dumbbell twisting bench press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento. Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial. Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1743-z6TAHoT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1743-z6TAHoT.gif'),
('0437', 'dumbbell upright row', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0437-ainizkb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0437-ainizkb.gif'),
('1765', 'dumbbell upright row (back pov)', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos y las palmas hacia tu cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos. Continúa subiendo hasta que las mancuernas estén a la altura de los hombros, con los codos apuntando hacia los lados. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1765-Iptlv6x.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1765-Iptlv6x.gif'),
('0864', 'dumbbell upright shoulder external rotation', 'shoulders', 'dumbbell', 'delts', 'rotator cuff', '{"rotator cuff","trapezius"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados. Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0864-x306lCW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0864-x306lCW.gif'),
('5201', 'dumbbell waiter biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén la parte superior de los brazos cerca del cuerpo y los codos pegados. Flexiona lentamente las mancuernas hacia los hombros, manteniendo las muñecas rectas. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/5201-KOpzGBL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/5201-KOpzGBL.gif'),
('0438', 'dumbbell w-press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","chest"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0438-vmwLyCg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0438-vmwLyCg.gif'),
('0439', 'dumbbell zottman curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante. Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos. En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0439-kXaIn5A.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0439-kXaIn5A.gif'),
('2294', 'dumbbell zottman preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla. Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba. En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2294-y5U5B9Y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2294-y5U5B9Y.gif'),
('2189', 'dumbbells seated triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Extiende los brazos y sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2189-FQXdXzY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2189-FQXdXzY.gif'),
('1167', 'dynamic chest stretch (male)', 'chest', 'body weight', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos hacia los lados, paralelos al suelo. Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo. Siente el estiramiento en los músculos del pecho. Mantén el estiramiento durante 10-30 segundos. Vuelve a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1167-3uj0Ozg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1167-3uj0Ozg.gif'),
('3287', 'elbow dips', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3287-LkoAWAE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3287-LkoAWAE.gif'),
('1772', 'elbow lift - reverse push-up', 'back', 'body weight', 'upper back', 'triceps', '{"triceps","shoulders"}', 'Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros. Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados. Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta. Baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1772-wbUYILZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1772-wbUYILZ.gif'),
('0443', 'elbow-to-knee', 'waist', 'body weight', 'abs', 'obliques', '{"obliques"}', 'Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda. Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0443-jvp6DiD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0443-jvp6DiD.gif');
